import java.util.List;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 27.02.22
 */
public abstract class Animal extends Actor
{
    protected int foodLevel;
    protected boolean female;
    protected boolean nocturnal;

    /**
     * Create a new animal at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Animal(Time time, Field field, Location location)
    {
        super(time, field, location);

    }

    /**
     * Initialize the shared state for a newborn animal.
     * @param nocturnal Whether the animal is nocturnal.
     * @param canGoLand Whether the animal can move on land.
     * @param canGoWater Whether the animal can move on water.
     * @param foodLevel The starting food level.
     * @param parentDiseases The diseases inherited from the parent.
     */
    protected void initializeNewbornState(boolean nocturnal, boolean canGoLand, boolean canGoWater, int foodLevel, Set<Disease> parentDiseases)
    {
        female = Randomizer.getRandom().nextBoolean();
        this.nocturnal = nocturnal;
        this.canGoLand = canGoLand;
        this.canGoWater = canGoWater;
        age = 0;
        this.foodLevel = foodLevel;
        inheritBirthDiseases(parentDiseases);
    }

    /**
     * Initialize the shared state for an animal that starts with a random age and food level.
     * @param nocturnal Whether the animal is nocturnal.
     * @param canGoLand Whether the animal can move on land.
     * @param canGoWater Whether the animal can move on water.
     * @param maxAge The exclusive upper bound for the initial age.
     * @param maxFood The exclusive upper bound for the initial food level.
     * @param actorName The actor name used for startup disease seeding.
     */
    protected void initializeRandomStartState(boolean nocturnal, boolean canGoLand, boolean canGoWater, int maxAge, int maxFood, String actorName)
    {
        female = Randomizer.getRandom().nextBoolean();
        this.nocturnal = nocturnal;
        this.canGoLand = canGoLand;
        this.canGoWater = canGoWater;
        age = Randomizer.getRandom().nextInt(maxAge);
        foodLevel = Randomizer.getRandom().nextInt(maxFood) + 1;
        seedStartingDiseases(actorName);
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * Checks if the time of day matches if the animal is nocturnal or not,
     * then attempts to find food and move.
     * @param newAnimals A list to receive newly born animals.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newAnimals, WeatherCond weather)
    {
        super.act(newAnimals,weather);
        incrementHunger();
        if(isAlive()&&(getTime().isDay() != nocturnal)) {
            giveBirth(newAnimals);            
            // Move towards a source of food if found.
            Location newLocation = null;
            if (getField().getWeatherAttributeValueAt("visibility", getLocation()) > 0.4){
                newLocation = findFood();
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(this, getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Checks if the animal is female and looks for a mate
     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        if (female&&findMate()) {
            super.giveBirth(newAnimals);
        }
    }

    /**
     * Searches for a mate to breed with.
     * Searches first for an adjacent animal of the same dynamic type,
     * then if that animal is male.
     * @return true if a mate is found.
     */
    protected boolean findMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()){
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            if (actor instanceof Animal) {
                Animal animal = (Animal) actor;
                if (animal.getActorName().equals(getActorName())&& !animal.female){
                    giveDiseases(animal);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Transfer diseases from the male mate to the female and vice versa.
     * @param mate The male mate that the female breeds with.
     */
    protected void giveDiseases(Animal mate)
    {
        for (Disease disease: mate.setDiseases){
            if (disease.isSpreadByBirth()){
                setDiseases.add(disease);
            }
        }
        for (Disease disease: setDiseases){
            if (disease.isSpreadByBirth()){
                mate.getActorDiseaseSet().add(disease);
            }
        }
    }

    /**
     * Look for rabbits adjacent to the current location.
     * Only the first live rabbit is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            if (field.canTraverse(this, where)) {
                Object actor = field.getObjectAt(where);
                if (actor instanceof Actor) {
                    Actor prey = (Actor) actor;
                    if(getPreyFoodValuesMap().containsKey(prey.getActorName()) && prey.isAlive()) {
                        for(Disease disease: prey.setDiseases){
                            if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getActorName())){
                                setDiseases.add(disease);
                            }
                        }
                        prey.setDead();
                        if (foodLevel + getPreyFoodValuesMap().get(prey.getActorName()) < getMaxFood()) {
                            foodLevel += getPreyFoodValuesMap().get(prey.getActorName());
                        }
                        else {
                            foodLevel = getMaxFood();
                        }
                        return where;
                    }
                }
            }
        }
        return null;
    }

    /**
     * Returns how many animals are produced during birth
     * @return The number of animals birthed
     */
    abstract protected int breed();

    /**
     * Creates a new animal 
     * @param location The new location of the child
     * @param Set<Disease> The diseases that the parent had is passed down
     * @return The new animal created
     */
    abstract protected Animal birth(Location loc, Set<Disease> parentDiseases);

    /**
     * Returns the Map of the prey of the animal and how much food they provide it
     * @return The Map of the prey of the animal and how much food they provide it
     */
    abstract protected Map<String, Integer> getPreyFoodValuesMap();

    /**
     * Returns the max food value that the animal can have
     * @return The max food value that the animal can have
     */
    abstract protected int getMaxFood();
}

import java.util.List;
import java.util.Set;
import java.util.HashSet;
import java.util.Random;

/**
 * A class representing shared characteristics of actors.
 *
 * @version 27.02.22
 */
public abstract class Actor
{
    // Whether the actor is alive or not.
    private boolean alive;
    // The actor's field.
    private Field field;
    // The actor's position in the field.
    private Location location;
    //The actor's age
    protected int age;
    //A reference to the time object of the simulation
    private Time time; 
    //The diseases that the actor has
    protected Set<Disease> setDiseases;
    //If the animal can go on water
    protected boolean canGoWater;
    //If the animal can go on land
    protected boolean canGoLand;

    /**
     * Create a new actor at location in field with time as well.
     * With a set that will add any disease that it catches
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param time The time in the simulation
     */
    public Actor(Time time, Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
        this.time = time;
        setDiseases = new HashSet<>();
    }

    /**
     * Make this actor act - that is: make it do
     * whatever it wants/needs to do.
     * Checks if the location it is in is land or water, if it is in a location where
     * it can not be in, it will die by either being on water when it can only be on land vice versa
     * @param newActors A list to receive newly born actors.
     * @param weather The weather condition of the simulation.
     */
    public void act(List<Actor> newActors, WeatherCond weather)
    {
        incrementAge();
        if(isAlive() && !field.canTraverse(this, location)) {
            setDead();
        }
    }

    /**
     * Check whether the actor is alive or not.
     * @return true if the actor is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the actor is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(this, location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the actor's location.
     * @return The actor's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the actor at the new location in the given field.
     * @param newLocation The actor's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(this, location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the actor's field.
     * @return The actor's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Return the time in the field.
     * @return The time.
     */
    protected Time getTime()
    {
        return time;
    }

    /**
     * Returns the actors Name
     * @return The actors name
     */
    abstract protected String getActorName();

    /**
     * Increments the actors age by 1
     * If the actor has a disease then the max age will decrease and if the current age
     * is greater than the maxAge then they will die.
     * Each disease reduces the maxAge by a certain amount.
     */
    private void incrementAge()
    {
        age++;
        int maxAge = getMaxAge();
        for(Disease disease : setDiseases){
            maxAge *= disease.getActorsAffectedMap().get(getActorName());
        }
        if(age > maxAge) {
            setDead();
        }

    }

    /**
     * Returns the actors max age
     * @return The max age
     */
    abstract protected int getMaxAge();

    /**
     * Checks if there is free locations and places the offspring there
     * If the parent has diseases then those transferred by birth it will be transfered to the child
     * @param newActors The List of new actors that have been born to add to the simulator List of actors
     */
    protected void giveBirth(List<Actor> newActors)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(this, getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Actor young = birth(loc, setDiseases);
            newActors.add(young);
        }
    }

    /**
     * Copy birth-spread diseases from a parent into this actor.
     * @param parentDiseases The parent's diseases.
     */
    protected void inheritBirthDiseases(Set<Disease> parentDiseases)
    {
        for(Disease disease : parentDiseases) {
            if(disease.isSpreadByBirth()) {
                setDiseases.add(disease);
            }
        }
    }

    /**
     * Seed this actor with any diseases it can start with.
     * @param actorName The actor name used for disease lookup.
     */
    protected void seedStartingDiseases(String actorName)
    {
        Random random = Randomizer.getRandom();
        for(Disease disease : Simulator.diseases) {
            Double startingProbability = disease.getStartingActorsMap().get(actorName);
            if(startingProbability != null && random.nextDouble() <= startingProbability) {
                setDiseases.add(disease);
            }
        }
    }

    /**
     * Determine how many offspring this actor can produce.
     * @param breedingAge The minimum age required to breed.
     * @param breedingProbability The chance of a successful breeding attempt.
     * @param maxLitterSize The largest number of offspring produced.
     * @param random The random source for breeding.
     * @return The number of offspring.
     */
    protected int breedOffspringCount(int breedingAge, double breedingProbability, int maxLitterSize, Random random)
    {
        if(age >= breedingAge && random.nextDouble() <= breedingProbability) {
            return random.nextInt(maxLitterSize) + 1;
        }
        return 0;
    }

    /**
     * Returns if the actor can move on land
     * @return true if the actor can move on land
     */
    public boolean canMoveOnLand()
    {
        return canGoLand;
    }

    /**
     * Returns if the actor can move on water
     * @return true if the actor can move on water
     */
    public boolean canMoveOnWater()
    {
        return canGoWater;
    }

    /**
     * Return if the actor has a disease
     * @return true if the actor has a disease
     */
    public boolean hasDisease(){
        return setDiseases.size() > 0;
    }

    /**
     * Returns the set of diseases the actor has
     * @return The set of diseases the actor has
     */
    public Set<Disease> getActorDiseaseSet()
    {
        return setDiseases;
    }

    /**
     * Returns how many actors are produced during birth
     * @return The number of actors birthed
     */
    abstract protected int breed();

